import{_ as a,o,c as t,ag as i}from"./chunks/framework.B7PviQjB.js";const n="/docs/images/files/images-viewer.png",p=JSON.parse('{"title":"View images","description":"View an uploaded image, zoom in and out, page through the images in a folder, and download the original.","frontmatter":{"title":"View images","description":"View an uploaded image, zoom in and out, page through the images in a folder, and download the original.","type":"how-to"},"headers":[],"relativePath":"files/images.md","filePath":"files/images.md"}'),r={name:"files/images.md"};function s(h,e,l,d,m,g){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="view-images" tabindex="-1">View images <a class="header-anchor" href="#view-images" aria-label="Permalink to &quot;View images&quot;">​</a></h1><p>View an uploaded image in the browser, zoom in, page through the other images in the same folder, and download the original.</p><p>An image is view-only: you can&#39;t edit it in Wafflebase.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>To add an image, <a href="/docs/files/upload.html">upload</a> a PNG, JPEG, GIF, or WebP file of up to 25 MB.</li><li>To put an image inside a doc, presentation, sheet, or board instead, insert it from that editor.</li></ul></div><h2 id="view-an-image" tabindex="-1">View an image <a class="header-anchor" href="#view-an-image" aria-label="Permalink to &quot;View an image&quot;">​</a></h2><p>Open the image from your documents list. A spinner shows while it loads, then the image is centered and fitted to the window. Images up to 2 MB also show a thumbnail in the documents list.</p><h2 id="zoom-in-and-out" tabindex="-1">Zoom in and out <a class="header-anchor" href="#zoom-in-and-out" aria-label="Permalink to &quot;Zoom in and out&quot;">​</a></h2><p>Use the zoom bar at the bottom of the viewer:</p><ul><li>Click the plus magnifier (<strong>Zoom in</strong>) or the minus magnifier (<strong>Zoom out</strong>). Each click changes the zoom by 25%.</li><li>The percentage between the buttons shows the current zoom, from 25% to 500%.</li></ul><p>Opening another image starts again at 100%.</p><h2 id="page-through-a-folder" tabindex="-1">Page through a folder <a class="header-anchor" href="#page-through-a-folder" aria-label="Permalink to &quot;Page through a folder&quot;">​</a></h2><p>Click the arrow on the right edge (<strong>Next image</strong>) or the left edge (<strong>Previous image</strong>) of the image. You can also press <code>→</code> or <code>←</code>.</p><p>The viewer moves through the other images in the same folder, sorted by title. An image at the workspace root moves through the other root images. An arrow appears only when there is an image on that side.</p><p><img src="'+n+'" alt="Image viewer with Previous and Next arrows at the sides and the zoom bar at 100%"></p><h2 id="leave-the-viewer" tabindex="-1">Leave the viewer <a class="header-anchor" href="#leave-the-viewer" aria-label="Permalink to &quot;Leave the viewer&quot;">​</a></h2><p>Click the back arrow (<strong>Back to documents</strong>) to the left of the title, or press <code>Escape</code>. You return to the folder the image is in.</p><h2 id="download-the-original" tabindex="-1">Download the original <a class="header-anchor" href="#download-the-original" aria-label="Permalink to &quot;Download the original&quot;">​</a></h2><p>Click the download icon (<strong>Download image</strong>) in the header. The original file downloads unchanged.</p><h2 id="rename-an-image" tabindex="-1">Rename an image <a class="header-anchor" href="#rename-an-image" aria-label="Permalink to &quot;Rename an image&quot;">​</a></h2><p>Click the title in the header, type a new name, and press <code>Enter</code>. To cancel, press <code>Escape</code>. An uploaded image starts with its file extension in its title, such as <code>beach.jpg</code>. If you remove the extension, a download still adds it back.</p><h2 id="share-an-image" tabindex="-1">Share an image <a class="header-anchor" href="#share-an-image" aria-label="Permalink to &quot;Share an image&quot;">​</a></h2><p>Click <strong>Share</strong> in the header to create a link. See <a href="/docs/collaborate/share.html">Share a document</a>.</p><p>A share link shows one image. The person who opens it can zoom and download it with <strong>Download file</strong>, but gets no <strong>Previous</strong> or <strong>Next</strong> arrows, no <strong>Back to documents</strong> button, and no <code>Escape</code> shortcut.</p><h2 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h2><p>The image fits the screen, and the zoom bar and arrows work the same. Tap the arrows to page through the folder. See <a href="/docs/start/phone.html">Use Wafflebase on a phone</a>.</p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>There is no editing, cropping, or rotation. To change an image, edit it in another app and upload the new version.</li><li>Images don&#39;t have comments.</li><li>If an image fails to load, the viewer shows <code>Couldn&#39;t load image.</code> Reload the page to try again.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/files/upload.html">Upload files</a> to add more images.</li><li><a href="/docs/collaborate/folders.html">Folders</a> to group images so you can page through them.</li><li><a href="/docs/docs-editor/images.html">Insert images in a doc</a> to place an image inside a document.</li></ul>',29)])])}const u=a(r,[["render",s]]);export{p as __pageData,u as default};
